/// <summary>
///     The <c>AVAPriceIncreaseUIBuilder</c> class is the UI builder class for <c>AVAPriceIncrease</c>
/// </summary>
class AVAPriceIncreaseUIBuilder extends SysOperationAutomaticUIBuilder
{
    AVAPriceIncreaseContract   contract;


    AVAPriceIncreaseSet                     frmAVAPriceIncreaseSet;
    PriceGroupId                            frmPriceGroupId;
    PriceDiscModule                         frmPriceDiscModule;
    PriceGroupType                          frmPriceGroupType;
    AVAPriceIncreasePriceDiscGroup          frmAVAPriceIncreasePriceDiscGroup;

    DialogField df_AVAPriceIncreaseSet;
    DialogField df_PriceGroupId;
    DialogField df_PriceDiscModule;
    DialogField df_PriceGroupType;


}

Method.Source:
/// <summary>
///    AVA <c>getContract</c> method.
/// </summary>
/// <returns>
///    <c>AVAPriceIncreaseContract</c> as return value
/// </returns>
private AVAPriceIncreaseContract getContract()
{
    if(!contract)
    {
        contract = this.dataContractObject() as AVAPriceIncreaseContract;
    }

    return contract;
}

/// <summary>
///    AVA <c>getFromDialog</c> method.
/// </summary>
public void getFromDialog()
{
    super();

    this.getContract().parmAVAPriceIncreaseSet(df_AVAPriceIncreaseSet.value());
    this.getContract().parmPriceGroupId(df_PriceGroupId.value());
    this.getContract().parmPriceDiscModule(df_PriceDiscModule.value());
    this.getContract().parmPriceGroupType(df_PriceGroupType.value());
}

/// <summary>
///    AVA <c>postBuild</c> method.
/// </summary>
public void postBuild()
{
    super();

    // get references to dialog controls after creation
    df_AVAPriceIncreaseSet  = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                methodStr(AVAPriceIncreaseContract, parmAVAPriceIncreaseSet));
    df_PriceGroupId         = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                methodStr(AVAPriceIncreaseContract, parmPriceGroupId));
    df_PriceDiscModule      = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                methodStr(AVAPriceIncreaseContract, parmPriceDiscModule));
    df_PriceGroupType       = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                methodStr(AVAPriceIncreaseContract, parmPriceGroupType));

    df_AVAPriceIncreaseSet.enabled(false);
    df_PriceGroupId.enabled(false);
    df_PriceDiscModule.enabled(false);
    df_PriceGroupType.enabled(false);
}

/// <summary>
///    AVA <c>postRun</c> method.
/// </summary>
public void postRun()
{
    super();

    //modified
    df_AVAPriceIncreaseSet.registerOverrideMethod(  methodStr(FormStringControl, modified),
                                                    methodStr(AVAPriceIncreaseUIBuilder, modifiedAVAPriceIncreaseSet),
                                                    this);
    df_PriceGroupId.registerOverrideMethod(         methodStr(FormStringControl, modified),
                                                    methodStr(AVAPriceIncreaseUIBuilder, modifiedPriceGroupId),
                                                    this);
    df_PriceDiscModule.registerOverrideMethod(      methodstr(FormStringControl, modified),
                                                    methodstr(AVAPriceIncreaseUIBuilder, modifiedPriceDiscModule),
                                                    this);
    df_PriceGroupType.registerOverrideMethod(       methodstr(FormStringControl, modified),
                                                    methodstr(AVAPriceIncreaseUIBuilder, modifiedPriceGroupType),
                                                    this);
}

